import fs from"fs";import path from"path";export function validateHtmlFiles(e=process.cwd()){const t=[],s=["viewport","description"],n=fs.readdirSync(e).filter(e=>e.endsWith(".html"));return n.forEach(n=>{const i=path.join(e,n),a=fs.readFileSync(i,"utf8");s.forEach(e=>{a.includes(`name="${e}"`)||t.push({file:n,type:"missing_meta",meta:e})})}),{totalScanned:n.length,issuesCount:t.length,issues:t}}if(process.argv[1]&&process.argv[1].endsWith("pr-health-checker.js")){const e=validateHtmlFiles();console.log(`PR Health Checker Scanned ${e.totalScanned} HTML files with ${e.issuesCount} warnings.`)}